for i,cl in enumerate(clauses):
    for v in cl:
        occ_id[(i,v)]=next_elem
        next_elem+=1
universe_size=next_elem
sets=[]
for i,cl in enumerate(clauses):
    for v in cl:
        sets.append([i, occ_id[(i,v)]])
for (i,v),eid in occ_id.items():
    sets.append([eid])

u=universe_size
full=(1<<u)-1
masks=[]
for s in sets:
    mask=0
    for e in s:
        mask|=1<<e
    masks.append(mask)

for r in range(1<<len(sets)):
    used=0
    ok=True
    for i in range(len(sets)):
        if r>>i & 1:
            if used & masks[i]:
                ok=False;break
            used|=masks[i]
    if ok and used==full:
        print('found cover')
        break
else:
    print('none')
